"Só um modo de cada vez. Com qualquer modo ligado as notificações ficam silenciosas e sem avisos flutuantes, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Tylko jeden tryb naraz. Przy włączonym dowolnym trybie powiadomienia są ciche i bez wyskakujących alertów, jak w \"Nie przeszkadzać\"; Praca i Sen nie mają jeszcze list dozwolonych aplikacji.",
"Só um foco de cada vez. Com qualquer foco ligado as notificações ficam silenciosas e sem banners, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Tylko jedno skupienie naraz. Przy włączonym dowolnym skupieniu powiadomienia są ciche i bez banerów, jak w \"Nie przeszkadzać\"; Praca i Sen nie mają jeszcze list dozwolonych aplikacji.",
