"Apps externas: autorizações no servidor": "Aplikacje zewnętrzne: uprawnienia na serwerze",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada nas apps recentes ou quando sais.": "Co serwer pozwala każdej aplikacji zewnętrznej robić w Twoim imieniu. \"Jednorazowo\" kończy się, gdy aplikacja zostanie zamknięta w ostatnich aplikacjach lub gdy wyjdziesz.",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada no alternador ou quando sais.": "Co serwer pozwala każdej aplikacji zewnętrznej robić w Twoim imieniu. \"Jednorazowo\" kończy się, gdy aplikacja zostanie zamknięta w przełączniku aplikacji lub gdy wyjdziesz.",
"%s · uma vez": "%s · jednorazowo",
"Serviços de localização": "Usługi lokalizacji",
"Apps que pediram acesso": "Aplikacje, które poprosiły o dostęp",
"Com os serviços de localização desligados nenhuma app recebe a tua posição, mesmo as que têm acesso.": "Przy wyłączonych usługach lokalizacji żadna aplikacja nie otrzymuje Twojej pozycji, nawet te z dostępem.",
"\"Permitido uma vez\" dura até a app ser fechada nas apps recentes.": "\"Dozwolone jednorazowo\" trwa do zamknięcia aplikacji w ostatnich aplikacjach.",
"\"Permitido uma vez\" dura até a app ser fechada no alternador.": "\"Dozwolone jednorazowo\" trwa do zamknięcia aplikacji w przełączniku aplikacji.",
"Permitido uma vez": "Dozwolone jednorazowo",
