"Recibos de leitura: desligados, quem te escreve deixa de ver \"Lida\" nas conversas contigo e tu também deixas de o ver nas tuas. Nos grupos as tuas leituras continuam a contar para quem enviou. Visto por último e online: desligado, ninguém vê se estás online nem quando estiveste pela última vez.": "Potwierdzenia odczytu: gdy wyłączone, osoby, które do Ciebie piszą, nie widzą już \"Przeczytano\" w rozmowach z Tobą, a Ty nie widzisz tego w swoich. W grupach Twoje odczyty nadal się liczą dla nadawcy. Ostatnio widziano i online: gdy wyłączone, nikt nie widzi, czy jesteś online ani kiedy ostatnio byłeś(aś).",
