"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Rozbij wszystkie cegły, nie gubiąc piłki. Ma wytrzymałe cegły, spadające bonusy i niekończące się poziomy. Rozbij wszystkie cegły, nie gubiąc piłki. Ma wytrzymałe cegły, spadające bonusy i niekończące się poziomy.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "Twoje pojazdy, ich lokalizacja i garaż. Lokalizuj, dodawaj do ulubionych, nadawaj pseudonimy.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Anonimowe pokoje według pseudonimu. Wiadomości są przechowywane na serwerze. Według pseudonimu. Wiadomości zostają na serwerze.",
