"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "Wszystkie gry z telefonu w jednym miejscu, z Twoimi rekordami i ostatnią grą. Wszystkie gry z telefonu w jednym miejscu, z Twoimi rekordami i ostatnią grą.",
