"Qualquer jogador pode instalar e usar o lado do cidadão (denúncias, marcações, pedidos, menus).": "Każdy gracz może zainstalować i używać strony obywatela (zgłoszenia, wizyty, prośby, menu).",
"O lado da equipa só aparece a quem está de serviço (o módulo Serviço continua visível para poder entrar).": "Strona zespołu jest widoczna tylko dla osób na służbie (moduł Służba pozostaje widoczny, aby można było ją rozpocząć).",
"Quem tem um destes empregos (e o grau mínimo) vê o lado da equipa. A lista e os graus vêm do framework.": "Osoby z jedną z tych prac (i minimalnym stopniem) widzą stronę zespołu. Lista i stopnie pochodzą z frameworka.",
"A lista de empregos do framework não respondeu. Escreve o nome do emprego e o grau à mão.": "Lista prac z frameworka nie odpowiedziała. Wpisz nazwę pracy i stopień ręcznie.",
